        'faqs' => [
            ['What does wait for FCC authorization mean?', 'It means the product, or a radio feature in it, has not yet received FCC authorisation. It can be advertised with a notice, but it cannot be sold or delivered in the USA until the grant is issued, and some makers enable the feature later with a firmware update.'],
        ],
